'use client'
import { normalizeProgress, useSignal, useSignals } from '@cascivo/core'
import type { ProgressInput } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import styles from './steps.module.css'

/**
 * The catalog-wide progress vocabulary. `Timeline`'s `current` / `upcoming` are accepted as
 * aliases of `active` / `pending`, so one status enum drives both components — writing
 * `state: 'upcoming'` here used to be a type error with no hint that `pending` was the word.
 */
export type StepState = 'pending' | 'active' | 'complete' | 'error'

export interface Step {
  label: string
  /**
   * Stable identity for the step, used as its React key.
   *
   * Every other config-item type in the catalog (`TimelineItem`, `SideNavItem`,
   * `DataListItem`, `BreadcrumbItem`) carries one; `Step` was missed because the sweep that
   * added them looked for a `label` **and an `href`** (2026-08-22 report item 10). Without it
   * the index is the key, so reordering or inserting a step re-uses the wrong DOM node.
   */
  id?: string
  /**
   * Step status. `StepState` is the canonical enum; `ProgressInput` additionally accepts
   * Timeline's `current` / `upcoming` aliases so one status value drives both components.
   */
  state?: StepState | ProgressInput
}

/** Props shared by both spellings of the collection. */
interface StepsBaseProps {
  /**
   * Index of the currently active step (0-based)
   *
   * @defaultValue `0`
   * @see the component manifest
   */
  activeStep?: number
  orientation?: 'horizontal' | 'vertical'
  className?: string
  /** Accessible label for the steps list */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
}

/**
 * The collection, under either spelling — exactly one is required.
 *
 * `steps` is the domain word and stays canonical. `items` is accepted because the catalog's
 * published data-prop vocabulary says a config-driven collection is `items`, and an adopter
 * who followed that rule hit a type error on the one component the rule named wrongly
 * (2026-08-22 report item 10). The XOR keeps "pass neither" and "pass both" compile errors
 * rather than silent no-ops, the same shape `Menubar` uses for its name props.
 */
type StepsCollection = { steps: Step[]; items?: never } | { items: Step[]; steps?: never }

export type StepsProps = StepsBaseProps & StepsCollection

export function Steps({
  steps,
  items,
  activeStep: controlledActiveStep,
  orientation = 'horizontal',
  className,
  ariaLabel,
  label,
}: StepsProps) {
  useSignals()
  const resolvedSteps = items ?? steps ?? []
  const active = useSignal(controlledActiveStep ?? 0)
  active.value = controlledActiveStep ?? active.value
  const resolvedAriaLabel = ariaLabel ?? label ?? t(builtin.steps.label)

  return (
    <ol
      className={[styles.steps, className].filter(Boolean).join(' ')}
      data-orientation={orientation}
      aria-label={resolvedAriaLabel}
    >
      {resolvedSteps.map((step, i) => {
        const state: StepState = step.state
          ? normalizeProgress(step.state)
          : i < active.value
            ? 'complete'
            : i === active.value
              ? 'active'
              : 'pending'
        return (
          <li
            key={step.id ?? i}
            className={styles.step}
            data-state={state}
            aria-current={state === 'active' ? 'step' : undefined}
          >
            <div className={styles.circle}>
              {state === 'complete' ? '✓' : state === 'error' ? '✕' : i + 1}
            </div>
            <span className={styles.label}>{step.label}</span>
          </li>
        )
      })}
    </ol>
  )
}

@layer cascivo.component {
  .steps {
    display: flex;
    gap: 0;
    list-style: none;
    margin: 0;
    padding: 0;
  }

  .steps[data-orientation='horizontal'] {
    flex-direction: row;
    align-items: center;
  }
  .steps[data-orientation='vertical'] {
    flex-direction: column;
  }

  .step {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex: 1;
    position: relative;
  }

  .step:not(:last-child)::after {
    content: '';
    flex: 1;
    block-size: 1px;
    background-color: var(--cascivo-border-default);
  }

  .steps[data-orientation='vertical'] .step:not(:last-child)::after {
    position: absolute;
    inset-inline-start: 0.75rem;
    inset-block-start: 2rem;
    inline-size: 1px;
    block-size: calc(100% - 1.5rem);
    flex: none;
  }

  .circle {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    border-radius: var(--cascivo-radius-full);
    border: 2px solid var(--cascivo-border-default);
    background-color: var(--cascivo-color-surface);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--cascivo-color-text-muted);
    flex-shrink: 0;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out);
  }

  .step[data-state='active'] .circle {
    background-color: var(--cascivo-color-accent);
    border-color: var(--cascivo-color-accent);
    color: var(--cascivo-color-accent-content);
  }

  .step[data-state='complete'] .circle {
    background-color: var(--cascivo-color-success);
    border-color: var(--cascivo-color-success);
    color: var(--cascivo-color-success-content);
  }

  .step[data-state='error'] .circle {
    background-color: var(--cascivo-color-error);
    border-color: var(--cascivo-color-error);
    color: var(--cascivo-color-error-content);
  }

  .step[data-state='complete']:not(:last-child)::after {
    background-color: var(--cascivo-color-success);
  }

  .label {
    font-size: 0.875rem;
    color: var(--cascivo-color-text-subtle);
  }

  .step[data-state='active'] .label {
    color: var(--cascivo-color-text);
    font-weight: 500;
  }
  .step[data-state='complete'] .label {
    color: var(--cascivo-color-text-subtle);
  }
  .step[data-state='error'] .label {
    color: var(--cascivo-color-destructive-foreground);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Steps',
  description:
    'Visual progress indicator for multi-step flows with horizontal and vertical orientations',
  category: 'navigation',
  // A static progress indicator; every step and its state render on the server.
  clientJs: 'enhancement',
  states: ['pending', 'active', 'complete', 'error'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description:
        'Accessible label for the steps navigation; defaults to the built-in i18n string.',
    },
    {
      name: 'items',
      description:
        'Alias of `steps` — the catalog-wide name for a config-driven collection. Exactly one of the two is required.',
      type: 'Step[]',
      required: false,
    },
    {
      name: 'steps',
      type: 'Step[]',
      required: false,
      description: 'Array of step objects with label and optional explicit state',
    },
    {
      name: 'activeStep',
      type: 'number',
      required: false,
      default: '0',
      description: 'Index of the currently active step (0-based)',
    },
    {
      name: 'orientation',
      type: "'horizontal' | 'vertical'",
      required: false,
      default: "'horizontal'",
      description:
        'Axis the steps flow along: `horizontal` runs them across with connectors between, `vertical` stacks them down the page.',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  typeDefs: [
    {
      name: 'Step',
      description: 'Shape of an entry in `steps` / `items`.',
      fields: [
        { name: 'label', type: 'string', required: true, description: 'Visible step label.' },
        {
          name: 'id',
          type: 'string',
          required: false,
          description: 'Stable identity, used as the React key so reordering keeps DOM nodes.',
        },
        {
          name: 'state',
          type: 'StepState | ProgressInput',
          required: false,
          description:
            "Step status. `StepState` ('pending' | 'active' | 'complete' | 'error') is canonical; `ProgressInput` also accepts Timeline's `current` / `upcoming` aliases.",
        },
      ],
    },
  ],
  tokens: [
    '--cascivo-color-accent',
    '--cascivo-color-accent-content',
    '--cascivo-color-success',
    '--cascivo-color-success-content',
    '--cascivo-color-error',
    '--cascivo-color-error-content',
    '--cascivo-color-surface',
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
    '--cascivo-color-text-muted',
    '--cascivo-border-default',
    '--cascivo-radius-full',
    '--cascivo-ease-out',
  ],
  accessibility: {
    role: 'list',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    {
      title: 'Horizontal (default)',
      description: 'Standard checkout or onboarding progress tracker',
      code: `<Steps
  steps={[
    { label: 'Cart' },
    { label: 'Shipping' },
    { label: 'Payment' },
    { label: 'Confirm' },
  ]}
  activeStep={1}
/>`,
    },
    {
      title: 'Vertical',
      description: 'Sidebar-style progress for tall forms',
      code: `<Steps
  orientation="vertical"
  steps={[
    { label: 'Account info' },
    { label: 'Profile details' },
    { label: 'Preferences' },
  ]}
  activeStep={0}
/>`,
    },
    {
      title: 'With explicit error state',
      description: 'Override derived state on a specific step',
      code: `<Steps
  steps={[
    { label: 'Upload' },
    { label: 'Validate', state: 'error' },
    { label: 'Process' },
  ]}
  activeStep={1}
/>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['steps', 'wizard', 'stepper', 'progress', 'navigation', 'onboarding', 'checkout'],
  intent: {
    whenToUse: [
      'Checkout flows where the user moves through a fixed sequence of screens',
      'Onboarding wizards with a known number of steps',
      'Multi-step forms where showing overall progress reduces abandonment',
    ],
    whenNotToUse: [
